package org.apache.commons.math.analysis;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.FunctionEvaluationException;
import org.apache.commons.math.MaxIterationsExceededException;
import org.apache.commons.math3.exception.MaxIterationsExceededException;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.mockito.Mockito.*;

public class BrentSolver_solve_TriageGen0Test {

    /**
     * Note: Since the provided code snippet contains a logic bug (the 'else if (true)' 
     * block makes the IllegalArgumentException unreachable), these tests are written 
     * to reflect the actual control flow provided in the snippet.
     */

    @Test
    public void testSolve_RootAtMin() throws MaxIterationsExceededException, FunctionEvaluationException {
        // yMin = 0, yMax = 1. sign = 0.
        UnivariateRealFunction f = x -> x; 
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(0.0, 1.0);
        assertEquals(0.0, result, 1e-15);
    }

    @Test
    public void testSolve_RootAtMax() throws MaxIterationsExceededException, FunctionEvaluationException {
        // yMin = 1, yMax = 0. sign = 0.
        UnivariateRealFunction f = x -> 1.0 - x;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(0.0, 1.0);
        assertEquals(1.0, result, 1e-15);
    }

    @Test
    public void testSolve_BracketingRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // yMin = -1, yMax = 1. sign = -1.
        UnivariateRealFunction f = x -> x - 0.5;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(0.0, 1.0);
        // Brent's method should find the root 0.5
        assertEquals(0.5, result, 1e-7);
    }

    @Test
    public void testSolve_SameSign_MinIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // yMin = 0, yMax = 5. sign = 0.
        // This hits the 'else' (sign == 0) block and then 'if (yMin == 0.0)'
        UnivariateRealFunction f = x -> x * 5;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(0.0, 1.0);
        assertEquals(0.0, result, 1e-15);
    }

    @Test
    public void testSolve_SameSign_MaxIsRoot() throws MaxIterationsExceededException, FunctionEvaluationException {
        // yMin = 5, yMax = 0. sign = 0.
        // This hits the 'else' (sign == 0) block and then 'else' (yMin != 0)
        UnivariateRealFunction f = x -> 5.0 - 5.0 * x;
        BrentSolver solver = new BrentSolver(f);

        double result = solver.solve(0.0, 1.0);
        assertEquals(1.0, result, 1e-15);
    }

    @Test
    public void testSolve_SameSign_MinCloseToZero() throws MaxIterationsExceededException, FunctionEvaluationException {
        // To trigger 'if (sign > 0)' and 'if (Math.abs(yMin) <= functionValueAccuracy)'
        // We need a mock or a function where yMin is very small but positive.
        // Assuming functionValueAccuracy is a small positive constant (e.g., 1e-10)

        UnivariateRealFunction f = x -> {
            if (x == 0.0) return 1e-15; // very small positive
            return 1.0;
        };

        // We must ensure the solver's internal functionValueAccuracy is large enough 
        // to catch 1e-15, or use a function that returns 0 for min.
        // Given we can't change accuracy easily via constructor in this snippet, 
        // we assume the logic path is testable.

        BrentSolver solver = new BrentSolver(f) {
            // Overriding or using a setup where accuracy is met
        };

        // If the provided code has 'else if (true)', the IllegalArgumentException 
        // branch is logically dead. The 'sign > 0' branch will always hit 'else if (true)'.

        UnivariateRealFunction f2 = x -> 1.0; // yMin = 1, yMax = 1. sign = 1.
        BrentSolver solver2 = new BrentSolver(f2);
        double result = solver2.solve(0.0, 1.0);
        // Based on the code: sign > 0 -> if (abs(yMin) <= acc) -> else if (true) -> ret = max
        assertEquals(1.0, result, 1e-15);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testSolve_InvalidInterval() throws MaxIterationsExceededException, FunctionEvaluationException {
        // verifyInterval(min, max) usually throws if min >= max
        UnivariateRealFunction f = x -> x;
        BrentSolver solver = new BrentSolver(f);
        solver.solve(1.0, 0.0);
    }
}
